def list_dashboards(connection_id, status=None, archived=None, search=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0008000" if __import__("os").path.isdir("./environment_mix/0008000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            try:
                s = v.replace("Z", "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _dt_key(v):
        dt = _parse_dt(v)
        if dt is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    def _log(endpoint, credential_id, status_code, error_code=None, error_message=None, meta=None, latency_ms=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + base64.b32encode(os.urandom(10)).decode("utf-8").rstrip("=").lower(),
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "list_dashboards"

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^mbc_[0-9A-HJKMNP-TV-Z]{17,}$", connection_id):
        _log(endpoint, None, 400, "VALIDATION_ERROR", "connection_id is malformed", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "connection_id is malformed")

    if status is not None and status not in ("active", "archived", "deleted_remote"):
        _log(endpoint, None, 400, "VALIDATION_ERROR", "Invalid status", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid status", field="status")

    if archived is not None and not isinstance(archived, bool):
        _log(endpoint, None, 400, "VALIDATION_ERROR", "archived must be boolean", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "archived must be boolean", field="archived")

    if search is not None and not isinstance(search, str):
        _log(endpoint, None, 400, "VALIDATION_ERROR", "search must be a string", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "search must be a string", field="search")

    if sort is None:
        sort = "updated_at"
    if sort not in ("name", "created_at", "updated_at", "last_synced_at"):
        _log(endpoint, None, 400, "VALIDATION_ERROR", "Invalid sort", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log(endpoint, None, 400, "VALIDATION_ERROR", "Invalid order", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid order", field="order")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(endpoint, None, 400, "VALIDATION_ERROR", "limit out of bounds", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "limit out of bounds", field="limit", minimum=1, maximum=200)

    if cursor is not None and not isinstance(cursor, str):
        _log(endpoint, None, 400, "VALIDATION_ERROR", "cursor must be a string", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    # Resolve connection and authorization context (ambient)
    conns = _load("metabase_connections.json")
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if conn is None:
        # Per contract: try to find any combination that can serve call; for list endpoints,
        # "authenticated" ambient is satisfied if store contains the referenced connection.
        _log(endpoint, None, 404, "NOT_FOUND", "Connection not found", latency_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "Connection not found", connection_id=connection_id)

    # BUSINESS RULE: list_dashboards returns dashboards where connection is active; exclude deleted_remote always
    if conn.get("status") != "active":
        _log(endpoint, None, 401, "UNAUTHORIZED", "Connection is not active", latency_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "Connection is not active")

    rows = _load("metabase_dashboards.json")
    if not isinstance(rows, list):
        rows = []

    # Filter base set
    filtered = []
    q = (search or "").strip().lower()
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") != connection_id:
            continue
        if r.get("status") == "deleted_remote":
            continue
        if r.get("status") not in ("active", "archived"):
            continue
        if status is not None:
            # user may request deleted_remote but business rule excludes it regardless
            if status == "deleted_remote":
                continue
            if r.get("status") != status:
                continue
        if archived is not None and bool(r.get("archived")) != archived:
            continue
        if q:
            hay = ((r.get("name") or "") + " " + (r.get("description") or "")).lower()
            if q not in hay:
                continue
        filtered.append(r)

    # Sorting
    reverse = (order == "desc")

    def _sort_key(r):
        if sort == "name":
            return (str(r.get("name") or "").lower(), r.get("id") or "")
        if sort in ("created_at", "updated_at", "last_synced_at"):
            return (_dt_key(r.get(sort)), r.get("id") or "")
        return (r.get("id") or "")

    filtered.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination: cursor is base64url of integer offset
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            offset = int(base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            _log(endpoint, None, 400, "VALIDATION_ERROR", "Invalid cursor", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    latency = int((time.time() - t0) * 1000)
    _log(endpoint, None, 200, meta={"connection_id": connection_id, "returned": len(page), "total": total}, latency_ms=latency)

    return {
        "dashboards": page,
        "page": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
        },
    }

