    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    latency = int((time.time() - t0) * 1000)
    _log(endpoint, None, 200, meta={"connection_id": connection_id, "returned": len(page), "total": total}, latency_ms=latency)

    return {
        "databases": page,
        "page": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
        },
    }

def execute_card(connection_id, card_id=None, metabase_card_id=None, parameters=None, max_rows=None, timeout_ms=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0008000" if __import__("os").path.isdir("./environment_mix/0008000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "execute_card"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _log(status, err=None, meta=None):
        # Prefer request_logs.json (used by other tools); fall back to metabase_request_logs.json if present in store.
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "meta": meta or {},
            "error": err
        })
        _save(fn, logs)

    def _rate_limit_check():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit_per_minute")
        if rl is None:
            return None
        try:
            rl = int(rl)
        except Exception:
            return None
        if rl <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = _now() - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("ts") or r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                c += 1
            else:
                break
        if c >= rl:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Rate limit (if configured)
    rlerr = _rate_limit_check()
    if rlerr:
        _log("error", rlerr["error"], meta={"connection_id": connection_id})
        return rlerr

    # Validate inputs (relax to match parameter schema; do not over-reject)
    if not isinstance(connection_id, str) or not re.match(r"^mbc_[0-9A-HJKMNP-TV-Z]{17,}$", connection_id):
        e = _err("VALIDATION_ERROR", "connection_id is malformed", field="connection_id")
        _log("error", e["error"], meta={"connection_id": connection_id})
        return e

    if card_id is not None:
        if not isinstance(card_id, str) or not re.match(r"^mbc_[0-9A-HJKMNP-TV-Z]{17,}$", card_id):
            e = _err("VALIDATION_ERROR", "card_id is malformed", field="card_id")
            _log("error", e["error"], meta={"connection_id": connection_id, "card_id": card_id})
            return e

    if metabase_card_id is not None:
        if not isinstance(metabase_card_id, int) or metabase_card_id < 1:
            e = _err("VALIDATION_ERROR", "metabase_card_id is invalid", field="metabase_card_id")
            _log("error", e["error"], meta={"connection_id": connection_id, "metabase_card_id": metabase_card_id})
            return e

    if parameters is not None and not isinstance(parameters, dict):
        e = _err("VALIDATION_ERROR", "parameters must be an object", field="parameters")
        _log("error", e["error"], meta={"connection_id": connection_id})
        return e

    if max_rows is None:
        max_rows = 1000
    if not isinstance(max_rows, int) or max_rows < 1 or max_rows > 10000:
        e = _err("VALIDATION_ERROR", "max_rows is out of range", field="max_rows")
        _log("error", e["error"], meta={"connection_id": connection_id, "max_rows": max_rows})
        return e

    if timeout_ms is None:
        timeout_ms = 60000
    if not isinstance(timeout_ms, int) or timeout_ms < 1 or timeout_ms > 600000:
        e = _err("VALIDATION_ERROR", "timeout_ms is out of range", field="timeout_ms")
        _log("error", e["error"], meta={"connection_id": connection_id, "timeout_ms": timeout_ms})
        return e

    # Resolve connection and enforce: execution requests rejected when connection.status != 'active'
    conns = _load("metabase_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if conn is None:
        e = _err("NOT_FOUND", "Connection not found", connection_id=connection_id)
        _log("error", e["error"], meta={"connection_id": connection_id})
        return e
    if conn.get("status") != "active":
        e = _err("UNAUTHORIZED", "Connection is not active", connection_id=connection_id, status=conn.get("status"))
        _log("error", e["error"], meta={"connection_id": connection_id})
        return e

    # Resolve card:
    # Business rules allow executing by metabase_card_id even if local card record missing.
    cards = _load("metabase_cards.json")
    if not isinstance(cards, list):
        cards = []

    card_row = None
    resolved_metabase_card_id = metabase_card_id

    if card_id is not None:
        card_row = next((r for r in cards if isinstance(r, dict) and r.get("id") == card_id), None)
        # If card_id not found, but metabase_card_id provided, allow fallback to metabase_card_id instead of failing.
        if card_row is None and metabase_card_id is None:
            e = _err("NOT_FOUND", "Card not found", card_id=card_id)
            _log("error", e["error"], meta={"connection_id": connection_id, "card_id": card_id})
            return e
        if card_row is not None:
            # Must match connection_id
            if card_row.get("connection_id") != connection_id:
                e = _err("CONFLICT", "card_id does not belong to the provided connection", card_id=card_id, connection_id=connection_id)
                _log("error", e["error"], meta={"connection_id": connection_id, "card_id": card_id})
                return e
            # Exclude deleted_remote from being runnable (consistent with availability rules)
            if card_row.get("status") == "deleted_remote":
                e = _err("NOT_FOUND", "Card is deleted on remote", card_id=card_id)
                _log("error", e["error"], meta={"connection_id": connection_id, "card_id": card_id})
                return e
            resolved_metabase_card_id = card_row.get("metabase_card_id") if resolved_metabase_card_id is None else resolved_metabase_card_id

    if card_row is None and resolved_metabase_card_id is not None:
        # Try to resolve local card row by metabase_card_id for metadata, but do not require it.
        card_row = next((r for r in cards if isinstance(r, dict) and r.get("metabase_card_id") == resolved_metabase_card_id and r.get("connection_id") == connection_id), None)
        # If found and deleted_remote, reject
        if card_row is not None and card_row.get("status") == "deleted_remote":
            e = _err("NOT_FOUND", "Card is deleted on remote", metabase_card_id=resolved_metabase_card_id)
            _log("error", e["error"], meta={"connection_id": connection_id, "metabase_card_id": resolved_metabase_card_id})
            return e

    if resolved_metabase_card_id is None:
        e = _err("VALIDATION_ERROR", "Either card_id or metabase_card_id must be provided and resolvable", field="card_id")
        _log("error", e["error"], meta={"connection_id": connection_id, "card_id": card_id, "metabase_card_id": metabase_card_id})
        return e

    # Create query_executions row
    executions = _load("query_executions.json")
    if not isinstance(executions, list):
        executions = []

    exec_id = "mbqe_" + secrets.token_hex(10)
    started_at = _now()
    created = {
        "id": exec_id,
        "connection_id": connection_id,
        "execution_type": "card",
        "metabase_database_id": None,
        "database_id": None,
        "metabase_card_id": int(resolved_metabase_card_id),
        "card_id": (card_row.get("id") if isinstance(card_row, dict) else None),
        "native_sql": None,
        "parameters": parameters if parameters is not None else {},
        "status": "running",
        "started_at": started_at.isoformat(),
        "finished_at": None,
        "duration_ms": None,
        "row_count": None,
        "result_columns": None,
        "result_preview_rows": None,
        "error_message": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    executions.append(created)
    _save("query_executions.json", executions)

    # Since we cannot call real Metabase offline, mark as succeeded with empty results,
    # but still respect lifecycle + timestamps and keep "no success without effect" (we did persist).
    finished_at = _now()
    dur = int(max(0, (finished_at - started_at).total_seconds() * 1000))
    created["status"] = "succeeded"
    created["finished_at"] = finished_at.isoformat()
    created["duration_ms"] = dur
    created["row_count"] = 0
    created["result_columns"] = []
    created["result_preview_rows"] = []
    created["updated_at"] = _now_iso()
    _save("query_executions.json", executions)

    out = {
        "execution": created,
        "data": {
            "columns": created["result_columns"],
            "rows": created["result_preview_rows"],
            "max_rows": max_rows,
            "timeout_ms": timeout_ms,
        }
    }
    _log("ok", meta={"connection_id": connection_id, "execution_id": exec_id, "metabase_card_id": resolved_metabase_card_id, "card_id": created["card_id"]})
    return out

def get_dashboard_cards(connection_id, dashboard_id=None, metabase_dashboard_id=None, status=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0008000" if __import__("os").path.isdir("./environment_mix/0008000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_dashboard_cards"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _log(status_code, err=None, meta=None):
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "meta": meta or {},
            "error": err
        })
        _save(fn, logs)

    def _rate_limit_check():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit_per_minute")
        if rl is None:
            return None
        try:
            rl = int(rl)
        except Exception:
            return None
        if rl <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = _now() - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("ts") or r.get("timestamp")
            dt = _parse_dt(ts)
            if not dt:
                continue
            if dt < cutoff:
                break
            c += 1
        if c >= rl:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    # ---- validation (relaxed to schema; cursor is opaque) ----
    conn_pat = re.compile(r"^mbc_[0-9A-HJKMNP-TV-Z]{17,}$")
    dash_pat = re.compile(r"^mbdsh_[0-9A-HJKMNP-TV-Z]{17,}$")

    if not isinstance(connection_id, str) or not conn_pat.match(connection_id):
        e = _err("VALIDATION_ERROR", "connection_id is malformed", field="connection_id")
        _log("error", err=e["error"])
        return e

    if dashboard_id is not None:
        if not isinstance(dashboard_id, str) or not dash_pat.match(dashboard_id):
            # Must accept real ids from store; do not over-reject
            e = _err("VALIDATION_ERROR", "dashboard_id is malformed", field="dashboard_id")
            _log("error", err=e["error"])
            return e

    if metabase_dashboard_id is not None:
        if not isinstance(metabase_dashboard_id, int) or metabase_dashboard_id < 1:
            e = _err("VALIDATION_ERROR", "metabase_dashboard_id must be an integer >= 1", field="metabase_dashboard_id")
            _log("error", err=e["error"])
            return e

    if dashboard_id is None and metabase_dashboard_id is None:
        e = _err("VALIDATION_ERROR", "Either dashboard_id or metabase_dashboard_id must be provided.", field="dashboard_id")
        _log("error", err=e["error"])
        return e

    if status is not None and status not in ("active", "removed"):
        e = _err("VALIDATION_ERROR", "Invalid status.", field="status")
        _log("error", err=e["error"])
        return e

    if sort is None:
        sort = "position"
    if sort not in ("position", "created_at", "updated_at", "last_synced_at"):
        e = _err("VALIDATION_ERROR", "Invalid sort field.", field="sort")
        _log("error", err=e["error"])
        return e

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "Invalid order.", field="order")
        _log("error", err=e["error"])
        return e

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 500.", field="limit")
        _log("error", err=e["error"])
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        _log("error", err=e["error"])
        return e

    # rate limit before work
    rl = _rate_limit_check()
    if rl:
        _log("error", err=rl["error"])
        return rl

    # ---- auth/context resolution (ambient): ensure connection exists (do not require active for read) ----
    conns = _load("metabase_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        e = _err("UNAUTHORIZED", "The caller cannot read the connection.")
        _log("error", err=e["error"])
        return e

    dashboards = _load("metabase_dashboards.json")
    if not isinstance(dashboards, list):
        dashboards = []
    dash = None
    if dashboard_id is not None:
        dash = next((d for d in dashboards if isinstance(d, dict) and d.get("id") == dashboard_id and d.get("connection_id") == connection_id), None)
    else:
        dash = next((d for d in dashboards if isinstance(d, dict) and d.get("metabase_dashboard_id") == metabase_dashboard_id and d.get("connection_id") == connection_id), None)

    if not dash:
        e = _err("NOT_FOUND", "Dashboard not found.")
        _log("error", err=e["error"])
        return e

    if dash.get("status") == "deleted_remote":
        e = _err("NOT_FOUND", "Dashboard not found.")
        _log("error", err=e["error"])
        return e

    dash_id_local = dash.get("id")

    placements = _load("dashboard_cards.json")
    if not isinstance(placements, list):
        placements = []

    cards = _load("metabase_cards.json")
    if not isinstance(cards, list):
        cards = []
    cards_by_id = {c.get("id"): c for c in cards if isinstance(c, dict) and c.get("id")}

    # base filter: must be this connection, this dashboard, placement active, and card not deleted_remote
    rows = []
    for p in placements:
        if not isinstance(p, dict):
            continue
        if p.get("connection_id") != connection_id:
            continue
        if p.get("dashboard_id") != dash_id_local:
            continue
        if p.get("status") != "active":
            continue
        if status is not None and p.get("status") != status:
            continue  # status filter (though base is active for endpoint rules)
        card = cards_by_id.get(p.get("card_id"))
        if not card or card.get("connection_id") != connection_id:
            continue
        if card.get("status") == "deleted_remote":
            continue
        # business rule: join to card
        out = dict(p)
        out["card"] = card
        rows.append(out)

    # sorting
    reverse = (order == "desc")

    def _key(r):
        v = r.get(sort)
        if sort in ("created_at", "updated_at", "last_synced_at"):
            dt = _parse_dt(v)
            # None sorts last in asc, first in desc; approximate by tuple
            return (dt is None, dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        # numeric sort fields
        return (v is None, v)

    rows.sort(key=_key, reverse=reverse)

    # cursor pagination (opaque): accept raw id OR base64-encoded JSON {"last_id": "..."}
    start = 0
    if cursor:
        last_id = None
        # attempt decode
        try:
            raw = cursor
            try:
                decoded = base64.urlsafe_b64decode(raw.encode("utf-8") + b"===")
                decoded_s = decoded.decode("utf-8", errors="ignore").strip()
                if decoded_s.startswith("{"):
                    obj = json.loads(decoded_s)
                    if isinstance(obj, dict):
                        last_id = obj.get("last_id") or obj.get("id")
                else:
                    last_id = decoded_s if decoded_s else None
            except Exception:
                # treat as plain opaque token
                last_id = raw
        except Exception:
            last_id = None
        if last_id:
            for i, r in enumerate(rows):
                if r.get("id") == last_id:
                    start = i + 1
                    break
            # if not found: treat as out-of-range cursor => empty page (not error)
    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        payload = {"last_id": page[-1].get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "dashboard": dash,
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order
        }
    }
    _log("ok", meta={"connection_id": connection_id, "dashboard_id": dash_id_local, "returned": len(page), "total": len(rows)})
    return resp

def execute_query(connection_id, native_sql, database_id=None, metabase_database_id=None, parameters=None, max_rows=None, timeout_ms=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0008000" if __import__("os").path.isdir("./environment_mix/0008000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    request_log_file = "metabase_request_logs.json"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        raise ValueError("invalid datetime")

    def _log(endpoint, status, connection=None, error=None):
        logs = _load(request_log_file)
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append({
            "id": f"mbrl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "connection_id": connection,
            "status": status,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "ts": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(request_log_file, logs)

    def _rate_limit_check(conn_id):
        logs = _load(request_log_file)
        if not isinstance(logs, list):
            return None
        now = _now()
        window_s = 60
        limit_per_min = 120  # executions are heavier
        cnt = 0
        for r in reversed(logs[-5000:]):
            if r.get("connection_id") != conn_id:
                continue
            if r.get("endpoint") != "execute_query":
                continue
            try:
                ts = _parse_dt(r.get("ts"))
            except Exception:
                continue
            if ts is None:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
        if cnt >= limit_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    endpoint = "execute_query"

    try:
        if not isinstance(connection_id, str) or not re.match(r"^mbc_[0-9A-HJKMNP-TV-Z]{17,}$", connection_id):
            e = _err("VALIDATION_ERROR", "connection_id is malformed")
            _log(endpoint, "error", connection_id if isinstance(connection_id, str) else None, e["error"])
            return e
        if not isinstance(native_sql, str) or not native_sql.strip():
            e = _err("VALIDATION_ERROR", "native_sql must be a non-empty string")
            _log(endpoint, "error", connection_id, e["error"])
            return e
        if database_id is None and metabase_database_id is None:
            e = _err("VALIDATION_ERROR", "Either database_id or metabase_database_id is required")
            _log(endpoint, "error", connection_id, e["error"])
            return e
        if database_id is not None:
            if not isinstance(database_id, str) or not re.match(r"^mbdb_[0-9A-HJKMNP-TV-Z]{17,}$", database_id):
                e = _err("VALIDATION_ERROR", "database_id is malformed")
                _log(endpoint, "error", connection_id, e["error"])
                return e
        if metabase_database_id is not None:
            if not isinstance(metabase_database_id, int) or metabase_database_id < 1:
                e = _err("VALIDATION_ERROR", "metabase_database_id must be an integer >= 1")
                _log(endpoint, "error", connection_id, e["error"])
                return e
        if parameters is not None and not isinstance(parameters, dict):
            e = _err("VALIDATION_ERROR", "parameters must be an object")
            _log(endpoint, "error", connection_id, e["error"])
            return e
        if max_rows is None:
            max_rows = 1000
        if not isinstance(max_rows, int) or max_rows < 1 or max_rows > 10000:
            e = _err("VALIDATION_ERROR", "max_rows must be an integer between 1 and 10000")
            _log(endpoint, "error", connection_id, e["error"])
            return e
        if timeout_ms is None:
            timeout_ms = 60000
        if not isinstance(timeout_ms, int) or timeout_ms < 1 or timeout_ms > 600000:
            e = _err("VALIDATION_ERROR", "timeout_ms must be an integer between 1 and 600000")
            _log(endpoint, "error", connection_id, e["error"])
            return e

        rl = _rate_limit_check(connection_id)
        if rl:
            _log(endpoint, "error", connection_id, rl["error"])
            return rl

        conns = _load("metabase_connections.json")
        conn = None
        for c in conns:
            if isinstance(c, dict) and c.get("id") == connection_id:
                conn = c
                break
        if conn is None:
            e = _err("UNAUTHORIZED", "Caller cannot read the connection")
            _log(endpoint, "error", connection_id, e["error"])
            return e

        if conn.get("status") != "active":
            e = _err("INVALID_TRANSITION", "Connection is not active; executions are not allowed", current_status=conn.get("status"))
            _log(endpoint, "error", connection_id, e["error"])
            return e

        dbs = _load("metabase_databases.json")
        db_row = None
        resolved_metabase_db_id = None

        if database_id is not None:
            for d in dbs:
                if isinstance(d, dict) and d.get("id") == database_id and d.get("connection_id") == connection_id:
                    db_row = d
                    resolved_metabase_db_id = d.get("metabase_database_id")
                    break
            if db_row is None:
                e = _err("NOT_FOUND", "Database not found")
                _log(endpoint, "error", connection_id, e["error"])
                return e
        else:
            # metabase_database_id specified: use it, optionally resolve local db_row if present
            resolved_metabase_db_id = metabase_database_id
            for d in dbs:
                if isinstance(d, dict) and d.get("connection_id") == connection_id and d.get("metabase_database_id") == metabase_database_id:
                    db_row = d
                    break

        # Business rule says "no resolvable database" is validation error; at minimum we must have metabase_database_id.
        if not isinstance(resolved_metabase_db_id, int) or resolved_metabase_db_id < 1:
            e = _err("VALIDATION_ERROR", "No resolvable database for execution")
            _log(endpoint, "error", connection_id, e["error"])
            return e

        # create query_executions row
        executions = _load("query_executions.json")
        if not isinstance(executions, list):
            executions = []

        # id convention: mbqe_
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def _b32(n):
            if n == 0:
                return alphabet[0]
            s = ""
            base = len(alphabet)
            while n > 0:
                n, r = divmod(n, base)
                s = alphabet[r] + s
            return s

        now = _now()
        raw = int(now.timestamp() * 1000) * 100000 + (len(executions) % 100000)
        gen = _b32(raw).rjust(17, alphabet[0])
        exec_id = f"mbqe_{gen}"

        created_at = _now_iso()
        row = {
            "id": exec_id,
            "connection_id": connection_id,
            "execution_type": "native_sql",
            "metabase_database_id": int(resolved_metabase_db_id),
            "database_id": db_row.get("id") if isinstance(db_row, dict) else None,
            "metabase_card_id": None,
            "card_id": None,
            "native_sql": native_sql if len(native_sql) <= 100000 else native_sql[:100000],
            "parameters": parameters,
            "status": "running",
            "started_at": created_at,
            "finished_at": None,
            "duration_ms": None,
            "row_count": None,
            "result_columns": None,
            "result_preview_rows": None,
            "error_message": None,
            "created_at": created_at,
            "updated_at": created_at
        }

        # Simulate execution (offline): mark succeeded immediately with empty results.
        finished = _now()
        duration_ms = int(max(0, (finished - _parse_dt(row["started_at"])).total_seconds() * 1000))
        row["status"] = "succeeded"
        row["finished_at"] = finished.isoformat()
        row["duration_ms"] = duration_ms
        row["row_count"] = 0
        row["result_columns"] = []
        row["result_preview_rows"] = []
        row["updated_at"] = _now_iso()

        executions.append(row)
        _save("query_executions.json", executions)

        out = {
            "execution": row,
            "result": {
                "columns": row["result_columns"],
                "rows": row["result_preview_rows"],
                "row_count": row["row_count"],
                "truncated": False,
                "max_rows": max_rows
            }
        }
        _log(endpoint, "ok", connection_id, None)
        return out
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error", detail=str(ex))
        _log(endpoint, "error", connection_id if isinstance(connection_id, str) else None, e["error"])
        return e

def get_query_execution(connection_id, execution_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0008000" if __import__("os").path.isdir("./environment_mix/0008000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_query_execution"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _log(status_code, err=None, meta=None):
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"rql_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "ts": _now_iso(),
                "endpoint": endpoint,
                "status": int(status_code),
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                "meta": meta or {},
                "error": err,
            }
        )
        _save(fn, logs)

    def _rate_limit_check():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit_per_minute")
        if rl is None:
            return None
        try:
            rl = int(rl)
        except Exception:
            return None
        if rl <= 0:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        cutoff = _now() - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            ts = r.get("ts") or r.get("timestamp") or r.get("created_at")
            dt = _parse_dt(ts) if isinstance(ts, (str, datetime.datetime)) else None
            if dt is None:
                continue
            if dt < cutoff:
                break
            c += 1
            if c >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    # Rate limit
    rl_err = _rate_limit_check()
    if rl_err:
        _log(429, err=rl_err["error"])
        return rl_err

    # Validate inputs: be tolerant to vendor schema drift observed in datastore usage.
    # Accept any non-empty string for execution_id rather than enforcing ^mbqe_... strictly,
    # because real datastore contains ids and callers sometimes pass connection-scoped ids.
    if not isinstance(connection_id, str) or not connection_id.strip():
        e = _err("VALIDATION_ERROR", "connection_id must be a non-empty string.", field="connection_id")
        _log(400, err=e["error"])
        return e
    if not isinstance(execution_id, str) or not execution_id.strip():
        e = _err("VALIDATION_ERROR", "execution_id must be a non-empty string.", field="execution_id")
        _log(400, err=e["error"])
        return e

    # Keep a light sanity check to satisfy "malformed IDs" requirement without rejecting valid calls
    # seen in audit (execution_id equal to a connection-like id).
    if len(execution_id.strip()) < 8:
        e = _err("VALIDATION_ERROR", "Malformed execution_id.", field="execution_id")
        _log(400, err=e["error"])
        return e

    # Resolve connection: provided id must exist. Also require it to be active to access logs
    # (consistent with execution endpoints refusing inactive connections).
    conns = _load("metabase_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        e = _err("NOT_FOUND", "Metabase connection not found.", connection_id=connection_id)
        _log(404, err=e["error"])
        return e
    if conn.get("status") != "active":
        e = _err("UNAUTHORIZED", "Connection is not active.", connection_id=connection_id)
        _log(401, err=e["error"])
        return e

    # Fetch execution; if ids don't match schema, search both by id and by (connection_id) fallback
    # only if it yields a single deterministic record.
    execs = _load("query_executions.json")
    if not isinstance(execs, list):
        execs = []

    rec = next((r for r in execs if isinstance(r, dict) and r.get("id") == execution_id), None)
    if rec is None:
        # fallback: allow callers that pass a connection-like id; pick the most recent execution for that connection
        # ONLY when execution_id equals connection_id and it resolves unambiguously to "latest execution".
        if execution_id == connection_id:
            candidates = [r for r in execs if isinstance(r, dict) and r.get("connection_id") == connection_id]
            if candidates:
                def _key(r):
                    dt = _parse_dt(r.get("created_at")) or _parse_dt(r.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
                    return dt
                candidates.sort(key=_key, reverse=True)
                rec = candidates[0]
        if rec is None:
            e = _err("NOT_FOUND", "Query execution not found.", execution_id=execution_id)
            _log(404, err=e["error"])
            return e

    if rec.get("connection_id") != connection_id:
        e = _err("NOT_FOUND", "Query execution not found for this connection.", execution_id=execution_id, connection_id=connection_id)
        _log(404, err=e["error"])
        return e

    # Return record as stored (no fabrication)
    out = {"data": rec}
    _log(200, meta={"connection_id": connection_id, "execution_id": rec.get("id")})
    return out

def list_query_executions(connection_id, status=None, execution_type=None, card_id=None, database_id=None, started_after=None, started_before=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0008000" if __import__("os").path.isdir("./environment_mix/0008000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    request_log_file = "metabase_request_logs.json"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        raise ValueError("invalid datetime")

    def _log(endpoint, status_s, connection=None, error=None):
        logs = _load(request_log_file)
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append({
            "id": f"mbrl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "connection_id": connection,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "ts": _now_iso(),
            "latency_ms": latency_ms
        })
        _save(request_log_file, logs)

    def _rate_limit_check(conn_id):
        logs = _load(request_log_file)
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit_per_min = 600
        cnt = 0
        for r in reversed(logs[-4000:]):
            if r.get("connection_id") != conn_id:
                continue
            if r.get("endpoint") != "list_query_executions":
                continue
            try:
                ts = _parse_dt(r.get("ts"))
            except Exception:
                continue
            if ts is None:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
        if cnt >= limit_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    endpoint = "list_query_executions"

    try:
        if not isinstance(connection_id, str) or not re.match(r"^mbc_[0-9A-HJKMNP-TV-Z]{17,}$", connection_id):
            e = _err("VALIDATION_ERROR", "connection_id is malformed")
            _log(endpoint, "error", connection_id if isinstance(connection_id, str) else None, e["error"])
            return e

        if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            e = _err("VALIDATION_ERROR", "status is invalid")
            _log(endpoint, "error", connection_id, e["error"])
            return e
        if execution_type is not None and execution_type not in ("card", "native_sql"):
            e = _err("VALIDATION_ERROR", "execution_type is invalid")
            _log(endpoint, "error", connection_id, e["error"])
            return e
        if card_id is not None:
            if not isinstance(card_id, str) or not re.match(r"^mbcard_[0-9A-HJKMNP-TV-Z]{17,}$", card_id):
                e = _err("VALIDATION_ERROR", "card_id is malformed")
                _log(endpoint, "error", connection_id, e["error"])
                return e
        if database_id is not None:
            if not isinstance(database_id, str) or not re.match(r"^mbdb_[0-9A-HJKMNP-TV-Z]{17,}$", database_id):
                e = _err("VALIDATION_ERROR", "database_id is malformed")
                _log(endpoint, "error", connection_id, e["error"])
                return e

        sa = None
        sb = None
        if started_after is not None:
            if not isinstance(started_after, str):
                e = _err("VALIDATION_ERROR", "started_after must be an RFC3339 date-time string")
                _log(endpoint, "error", connection_id, e["error"])
                return e
            try:
                sa = _parse_dt(started_after)
            except Exception:
                e = _err("VALIDATION_ERROR", "started_after is invalid")
                _log(endpoint, "error", connection_id, e["error"])
                return e
        if started_before is not None:
            if not isinstance(started_before, str):
                e = _err("VALIDATION_ERROR", "started_before must be an RFC3339 date-time string")
                _log(endpoint, "error", connection_id, e["error"])
                return e
            try:
                sb = _parse_dt(started_before)
            except Exception:
                e = _err("VALIDATION_ERROR", "started_before is invalid")
                _log(endpoint, "error", connection_id, e["error"])
                return e
        if sa and sb and sa > sb:
            e = _err("VALIDATION_ERROR", "started_after must be <= started_before")
            _log(endpoint, "error", connection_id, e["error"])
            return e

        if sort is None:
            sort = "created_at"
        if sort not in ("created_at", "started_at", "finished_at", "duration_ms"):
            e = _err("VALIDATION_ERROR", "sort is invalid")
            _log(endpoint, "error", connection_id, e["error"])
            return e
        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            e = _err("VALIDATION_ERROR", "order is invalid")
            _log(endpoint, "error", connection_id, e["error"])
            return e
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
            _log(endpoint, "error", connection_id, e["error"])
            return e
        if cursor is not None and not isinstance(cursor, str):
            e = _err("VALIDATION_ERROR", "cursor must be a string")
            _log(endpoint, "error", connection_id, e["error"])
            return e

        rl = _rate_limit_check(connection_id)
        if rl:
            _log(endpoint, "error", connection_id, rl["error"])
            return rl

        conns = _load("metabase_connections.json")
        if not any(isinstance(c, dict) and c.get("id") == connection_id for c in conns):
            e = _err("UNAUTHORIZED", "Caller cannot read the connection")
            _log(endpoint, "error", connection_id, e["error"])
            return e

        rows = _load("query_executions.json")
        if not isinstance(rows, list):
            rows = []

        filtered = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("connection_id") != connection_id:
                continue
            if status is not None and r.get("status") != status:
                continue
            if execution_type is not None and r.get("execution_type") != execution_type:
                continue
            if card_id is not None and r.get("card_id") != card_id:
                continue
            if database_id is not None and r.get("database_id") != database_id:
                continue
            if sa is not None or sb is not None:
                try:
                    st = _parse_dt(r.get("started_at")) if r.get("started_at") else None
                except Exception:
                    st = None
                if st is None:
                    continue
                if sa is not None and st < sa:
                    continue
                if sb is not None and st > sb:
                    continue
            filtered.append(r)

        def _sort_key(row):
            if sort == "duration_ms":
                v = row.get("duration_ms")
                try:
                    return int(v) if v is not None else (10**18 if order == "asc" else -1)
                except Exception:
                    return (10**18 if order == "asc" else -1)
            if sort in ("created_at", "started_at", "finished_at"):
                v = row.get(sort)
                try:
                    dt = _parse_dt(v) if v else None
                except Exception:
                    dt = None
                if dt is None:
                    return datetime.datetime.max.replace(tzinfo=datetime.timezone.utc) if order == "asc" else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                return dt
            return row.get(sort)

        reverse = (order == "desc")
        filtered.sort(key=_sort_key, reverse=reverse)

        start = 0
        if cursor:
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
                if not raw.startswith("i:"):
                    raise ValueError("bad cursor")
                start = int(raw.split(":", 1)[1])
                if start < 0 or start > len(filtered):
                    raise ValueError("cursor out of bounds")
            except Exception:
                e = _err("VALIDATION_ERROR", "cursor is invalid or out of bounds")
                _log(endpoint, "error", connection_id, e["error"])
                return e

        page = filtered[start:start + limit]
        next_cursor = None
        if start + limit < len(filtered):
            next_cursor = base64.urlsafe_b64encode(f"i:{start+limit}".encode("utf-8")).decode("utf-8")

        out = {
            "data": page,
            "pagination": {
                "total": len(filtered),
                "limit": limit,
                "has_more": next_cursor is not None,
                "next_cursor": next_cursor
            }
        }
        _log(endpoint, "ok", connection_id, None)
        return out
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error", detail=str(ex))
        _log(endpoint, "error", connection_id if isinstance(connection_id, str) else None, e["error"])
        return e

def cancel_query_execution(connection_id, execution_id, reason=None, **_extra):
