                continue
            ts = r.get("ts") or r.get("timestamp") or r.get("created_at")
            dt = _parse_dt(ts) if isinstance(ts, (str, datetime.datetime)) else None
            if dt is None:
                continue
            if dt < cutoff:
                break
            c += 1
            if c >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    # Rate limit
    rl_err = _rate_limit_check()
    if rl_err:
        _log(429, err=rl_err["error"])
        return rl_err

    # Validate
    if not isinstance(connection_id, str) or not connection_id.strip():
        e = _err("VALIDATION_ERROR", "connection_id must be a non-empty string.", field="connection_id")
        _log(400, err=e["error"])
        return e
    if not isinstance(execution_id, str) or not execution_id.strip():
        e = _err("VALIDATION_ERROR", "execution_id must be a non-empty string.", field="execution_id")
        _log(400, err=e["error"])
        return e
    if reason is not None:
        if not isinstance(reason, str):
            e = _err("VALIDATION_ERROR", "reason must be a string.", field="reason")
            _log(400, err=e["error"])
            return e
        if len(reason) > 500:
            e = _err("VALIDATION_ERROR", "reason exceeds maxLength 500.", field="reason")
            _log(400, err=e["error"])
            return e

    # Resolve connection; must be active for execution mutations
    conns = _load("metabase_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        e = _err("NOT_FOUND", "Metabase connection not found.", connection_id=connection_id)
        _log(404, err=e["error"])
        return e
    if conn.get("status") != "active":
        e = _err("UNAUTHORIZED", "Connection is not active.", connection_id=connection_id)
        _log(401, err=e["error"])
        return e

    execs = _load("query_executions.json")
    if not isinstance(execs, list):
        execs = []

    idx = None
    rec = None
    for i, r in enumerate(execs):
        if isinstance(r, dict) and r.get("id") == execution_id:
            idx = i
            rec = r
            break

    if rec is None:
        # same tolerant fallback as get_query_execution, but cancellation must be deterministic
        if execution_id == connection_id:
            candidates = [(i, r) for i, r in enumerate(execs) if isinstance(r, dict) and r.get("connection_id") == connection_id]
            if candidates:
                def _key(ir):
                    r = ir[1]
                    dt = _parse_dt(r.get("created_at")) or _parse_dt(r.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
                    return dt
                candidates.sort(key=_key, reverse=True)
                idx, rec = candidates[0]
        if rec is None:
            e = _err("NOT_FOUND", "Query execution not found.", execution_id=execution_id)
            _log(404, err=e["error"])
            return e

    if rec.get("connection_id") != connection_id:
        e = _err("NOT_FOUND", "Query execution not found for this connection.", execution_id=execution_id, connection_id=connection_id)
        _log(404, err=e["error"])
        return e

    status = rec.get("status")
    terminal = {"succeeded", "failed", "cancelled"}
    if status in terminal:
        e = _err("CONFLICT", "Execution is already in a terminal state and cannot be cancelled.", status=status)
        _log(409, err=e["error"], meta={"connection_id": connection_id, "execution_id": rec.get("id")})
        return e

    if status not in {"queued", "running"}:
        # lifecycle rules: only queued->cancelled or running->cancelled are allowed here
        e = _err("INVALID_TRANSITION", "Execution cannot be cancelled from its current status.", from_status=status, to_status="cancelled")
        _log(409, err=e["error"], meta={"connection_id": connection_id, "execution_id": rec.get("id")})
        return e

    now = _now()
    started_at = _parse_dt(rec.get("started_at")) or now
    duration_ms = int(max(0, (now - started_at).total_seconds() * 1000))

    rec2 = dict(rec)
    rec2["status"] = "cancelled"
    rec2["finished_at"] = now.isoformat()
    rec2["started_at"] = started_at.isoformat()
    rec2["duration_ms"] = duration_ms
    rec2["updated_at"] = now.isoformat()
    if reason:
        # store in error_message for auditability without schema expansion
        # (field exists and is nullable)
        rec2["error_message"] = (reason[:500]).strip()

    execs[idx] = rec2
    _save("query_executions.json", execs)

    out = {"data": rec2}
    _log(200, meta={"connection_id": connection_id, "execution_id": rec2.get("id"), "from_status": status, "to_status": "cancelled"})
    return out

def create_metabase_connection(name, base_url, auth_type, username=None, password_secret_ref=None, api_key_secret_ref=None, **_extra):
    import json, os, datetime, time, urllib.parse, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0008000" if __import__("os").path.isdir("./environment_mix/0008000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_metabase_connection"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _log(status_code, err=None, meta=None):
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"rql_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "ts": _now_iso(),
                "endpoint": endpoint,
                "status": int(status_code),
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                "meta": meta or {},
                "error": err,
            }
        )
        _save(fn, logs)

    def _rate_limit_check():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit_per_minute")
        if rl is None:
            return None
        try:
            rl = int(rl)
        except Exception:
            return None
        if rl <= 0:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        cutoff = _now() - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            ts = r.get("ts") or r.get("timestamp") or r.get("created_at")
            dt = _parse_dt(ts) if isinstance(ts, (str, datetime.datetime)) else None
            if dt is None:
                continue
            if dt < cutoff:
                break
            c += 1
            if c >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _normalize_base_url(u):
        u = (u or "").strip()
        if not u:
            return None, _err("VALIDATION_ERROR", "base_url is required.", field="base_url")
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return None, _err("VALIDATION_ERROR", "base_url must be a valid URI.", field="base_url")
        if p.scheme not in ("http", "https") or not p.netloc:
            return None, _err("VALIDATION_ERROR", "base_url must include http(s) scheme and host.", field="base_url")
        # normalize: lowercase scheme/host, strip trailing slash, drop fragment, keep path if present
        netloc = p.netloc.lower()
        scheme = p.scheme.lower()
        path = p.path or ""
        if path != "/" and path.endswith("/"):
            path = path[:-1]
        if path == "/":
            path = ""
        norm = urllib.parse.urlunparse((scheme, netloc, path, "", "", ""))
        return norm, None

    # rate limit
    rl_err = _rate_limit_check()
    if rl_err:
        _log(429, err=rl_err["error"])
        return rl_err

    # validate name
    if not isinstance(name, str):
        e = _err("VALIDATION_ERROR", "name must be a string.", field="name")
        _log(400, err=e["error"])
        return e
    nm = name.strip()
    if not (1 <= len(nm) <= 200):
        e = _err("VALIDATION_ERROR", "name must be between 1 and 200 characters.", field="name")
        _log(400, err=e["error"])
        return e

    # validate base_url
    norm_url, e = _normalize_base_url(base_url)
    if e:
        _log(400, err=e["error"])
        return e

    # validate auth_type: tool accepts password/api_key; datastore uses session/api_key
    if not isinstance(auth_type, str):
        e = _err("VALIDATION_ERROR", "auth_type must be a string.", field="auth_type")
        _log(400, err=e["error"])
        return e
    at = auth_type.strip()
    if at not in ("password", "api_key"):
        e = _err("VALIDATION_ERROR", "Invalid auth_type. Must be one of: password, api_key.", field="auth_type")
        _log(400, err=e["error"])
        return e
    stored_auth_type = "session" if at == "password" else "api_key"

    # validate credential requirements
    if at == "password":
        if not isinstance(username, str) or not username.strip():
            e = _err("VALIDATION_ERROR", "username is required when auth_type='password'.", field="username")
            _log(400, err=e["error"])
            return e
        if not isinstance(password_secret_ref, str) or not password_secret_ref.strip():
            e = _err("VALIDATION_ERROR", "password_secret_ref is required when auth_type='password'.", field="password_secret_ref")
            _log(400, err=e["error"])
            return e
    if at == "api_key":
        if not isinstance(api_key_secret_ref, str) or not api_key_secret_ref.strip():
            e = _err("VALIDATION_ERROR", "api_key_secret_ref is required when auth_type='api_key'.", field="api_key_secret_ref")
            _log(400, err=e["error"])
            return e

    # load connections
    conns = _load("metabase_connections.json")
    if not isinstance(conns, list):
        conns = []

    # unique(base_url) constraint: compare normalized variants
    for c in conns:
        if not isinstance(c, dict):
            continue
        bu = c.get("base_url")
        if isinstance(bu, str):
            n2, _ = _normalize_base_url(bu)
            if n2 and n2 == norm_url:
                e = _err("CONFLICT", "A connection with this base_url already exists.", constraint="unique(base_url)", base_url=norm_url)
                _log(409, err=e["error"])
                return e

    # generate id: mbc_ + ULID-like (Crockford base32) 17+ chars
    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid_like(n=20):
        # 20 chars to comfortably satisfy {17,}
        import random
        ms = int(time.time() * 1000)
        # encode time into 10 chars base32 (approx ULID), then random remainder
        t = ms
        time_chars = []
        for _ in range(10):
            time_chars.append(alphabet[t % 32])
            t //= 32
        time_chars = "".join(reversed(time_chars))
        rand_chars = "".join(random.choice(alphabet) for _ in range(max(0, n - 10)))
        return time_chars + rand_chars

    now = _now_iso()
    new_row = {
        "id": f"mbc_{_ulid_like(20)}",
        "name": nm,
        "base_url": norm_url,
        "auth_type": stored_auth_type,
        "username": username.strip() if isinstance(username, str) and username.strip() else None,
        "password_secret_ref": password_secret_ref.strip() if isinstance(password_secret_ref, str) and password_secret_ref.strip() else None,
        "api_key_secret_ref": api_key_secret_ref.strip() if isinstance(api_key_secret_ref, str) and api_key_secret_ref.strip() else None,
        "status": "active",
        "last_healthcheck_at": None,
        "last_healthcheck_error": None,
        "created_at": now,
        "updated_at": now,
    }

    # enforce schema-level implications consistent with datastore schema
    if new_row["auth_type"] == "session":
        if not new_row.get("username") or not new_row.get("password_secret_ref"):
            e = _err("VALIDATION_ERROR", "auth_type='session' requires username and password_secret_ref.", constraint="auth_type=session implies username & password_secret_ref")
            _log(400, err=e["error"])
            return e
        new_row["api_key_secret_ref"] = None
    if new_row["auth_type"] == "api_key":
        if not new_row.get("api_key_secret_ref"):
            e = _err("VALIDATION_ERROR", "auth_type='api_key' requires api_key_secret_ref.", constraint="auth_type=api_key implies api_key_secret_ref")
            _log(400, err=e["error"])
            return e
        new_row["username"] = None
        new_row["password_secret_ref"] = None

    conns.append(new_row)
    _save("metabase_connections.json", conns)

    out = {"data": new_row}
    _log(201, meta={"connection_id": new_row["id"], "base_url": norm_url, "auth_type": new_row["auth_type"]})
    return out

def update_metabase_connection(connection_id, name=None, base_url=None, auth_type=None, username=None, password_secret_ref=None, api_key_secret_ref=None, status=None, last_healthcheck_error=None, **_extra):
    import json, os, datetime, re, time, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0008000" if __import__("os").path.isdir("./environment_mix/0008000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _log(status_s, err=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rql_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": "update_metabase_connection",
            "status": status_s,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "meta": meta or {"connection_id": connection_id},
            "error": err,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit_per_minute")
        if rl is None:
            return None
        try:
            rl = int(rl)
        except Exception:
            return None
        if rl <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs):
            ts = _parse_dt(r.get("ts"))
            if not ts:
                continue
            if ts < cutoff:
                break
            c += 1
            if c >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rl)
        return None

    rl_err = _rate_limit_check()
    if rl_err:
        _log("rate_limited", rl_err["error"])
        return rl_err

    try:
        if not isinstance(connection_id, str) or not re.match(r"^mbc_[0-9A-HJKMNP-TV-Z]{17,}$", connection_id):
            e = _err("VALIDATION_ERROR", "Invalid connection_id.", field="connection_id")
            _log("validation_error", e["error"])
            return e

        if name is not None:
            if not isinstance(name, str) or not (1 <= len(name) <= 200):
                e = _err("VALIDATION_ERROR", "Invalid name.", field="name")
                _log("validation_error", e["error"])
                return e
        if base_url is not None:
            if not isinstance(base_url, str) or not base_url.strip():
                e = _err("VALIDATION_ERROR", "Invalid base_url.", field="base_url")
                _log("validation_error", e["error"])
                return e
            p = urllib.parse.urlparse(base_url)
            if p.scheme not in ("http", "https") or not p.netloc:
                e = _err("VALIDATION_ERROR", "base_url must be a valid http(s) URI.", field="base_url")
                _log("validation_error", e["error"])
                return e
        if auth_type is not None:
            if not isinstance(auth_type, str) or auth_type not in ("password", "api_key"):
                e = _err("VALIDATION_ERROR", "Invalid auth_type.", field="auth_type")
                _log("validation_error", e["error"])
                return e
        if username is not None:
            if not isinstance(username, str) or not (1 <= len(username) <= 200):
                e = _err("VALIDATION_ERROR", "Invalid username.", field="username")
                _log("validation_error", e["error"])
                return e
        if password_secret_ref is not None:
            if not isinstance(password_secret_ref, str) or not (1 <= len(password_secret_ref) <= 500):
                e = _err("VALIDATION_ERROR", "Invalid password_secret_ref.", field="password_secret_ref")
                _log("validation_error", e["error"])
                return e
        if api_key_secret_ref is not None:
            if not isinstance(api_key_secret_ref, str) or not (1 <= len(api_key_secret_ref) <= 500):
                e = _err("VALIDATION_ERROR", "Invalid api_key_secret_ref.", field="api_key_secret_ref")
                _log("validation_error", e["error"])
                return e
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "disabled", "error"):
                e = _err("VALIDATION_ERROR", "Invalid status.", field="status")
                _log("validation_error", e["error"])
                return e
        if last_healthcheck_error is not None:
            if not isinstance(last_healthcheck_error, str) or len(last_healthcheck_error) > 2000:
                e = _err("VALIDATION_ERROR", "Invalid last_healthcheck_error.", field="last_healthcheck_error")
                _log("validation_error", e["error"])
                return e

        conns = _load("metabase_connections.json")
        if not isinstance(conns, list):
            conns = []
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if not conn:
            e = _err("NOT_FOUND", "Connection not found.", connection_id=connection_id)
            _log("not_found", e["error"])
            return e

        old_status = conn.get("status")
        old_auth = conn.get("auth_type")  # "session" or "api_key"

        # Apply auth_type update (tool: password/api_key -> schema: session/api_key)
        new_schema_auth = None
        if auth_type is not None:
            new_schema_auth = "session" if auth_type == "password" else "api_key"

        # base_url uniqueness (if updating)
        if base_url is not None:
            p = urllib.parse.urlparse(base_url)
            norm_base_url = urllib.parse.urlunparse((p.scheme, p.netloc, p.path.rstrip("/"), "", "", ""))
            for c in conns:
                if c.get("id") != connection_id and isinstance(c.get("base_url"), str) and c.get("base_url").rstrip("/") == norm_base_url:
                    e = _err("CONFLICT", "A connection with this base_url already exists.", base_url=norm_base_url, connection_id=c.get("id"))
                    _log("conflict", e["error"])
                    return e
            conn["base_url"] = norm_base_url

        if name is not None:
            conn["name"] = name

        if new_schema_auth is not None:
            conn["auth_type"] = new_schema_auth
            # When switching types, clear fields not applicable unless explicitly re-provided.
            if new_schema_auth == "session":
                conn["api_key_secret_ref"] = None
            else:
                conn["username"] = None
                conn["password_secret_ref"] = None

        # Apply credential field updates (do not force unless needed)
        if username is not None:
            conn["username"] = username
        if password_secret_ref is not None:
            conn["password_secret_ref"] = password_secret_ref
        if api_key_secret_ref is not None:
            conn["api_key_secret_ref"] = api_key_secret_ref

        # Lifecycle transition validation if status provided
        if status is not None and status != old_status:
            transitions = {
                "active": ["disabled", "error"],
                "disabled": ["active"],
                "error": ["active", "disabled"],
            }
            allowed = transitions.get(old_status, [])
            if status not in allowed:
                e = _err("INVALID_TRANSITION", "Illegal connection status transition.", from_status=old_status, to_status=status)
                _log("invalid_transition", e["error"])
                return e
            conn["status"] = status

        # healthcheck error update
        if last_healthcheck_error is not None:
            conn["last_healthcheck_error"] = last_healthcheck_error
            conn["last_healthcheck_at"] = _now_iso()

        # Enforce auth constraints in schema
        if conn.get("auth_type") == "session":
            if not conn.get("username") or not conn.get("password_secret_ref"):
                e = _err("VALIDATION_ERROR", "session auth requires username and password_secret_ref.")
                _log("validation_error", e["error"], meta={"connection_id": connection_id, "auth_type": conn.get("auth_type")})
                return e
        elif conn.get("auth_type") == "api_key":
            if not conn.get("api_key_secret_ref"):
                e = _err("VALIDATION_ERROR", "api_key auth requires api_key_secret_ref.")
                _log("validation_error", e["error"], meta={"connection_id": connection_id, "auth_type": conn.get("auth_type")})
                return e
        else:
            e = _err("VALIDATION_ERROR", "Invalid stored auth_type.", auth_type=conn.get("auth_type"))
            _log("validation_error", e["error"])
            return e

        conn["updated_at"] = _now_iso()
        _save("metabase_connections.json", conns)
        _log("ok", None, meta={"connection_id": connection_id, "status": conn.get("status"), "auth_type": conn.get("auth_type")})
        return {"connection": conn}
    except Exception as e:
        err = _err("CONFLICT", "Unexpected server error.", detail=str(e))
        _log("error", err["error"])
        return err
